#define sat(a) clamp(a, 0., 1.)
#define rot(a) mat2(cos(a), -sin(a), sin(a), cos(a))
float _seed;
float hash(float seed) { return fract(sin(seed*123.456)*123.456); }
float rand() { return hash(_seed++); }

vec2 _min(vec2 a, vec2 b)
{
    if (a.x < b.x)
        return a;
    return b;
}

float _sqr(vec2 uv, vec2 s)
{
    vec2 l = abs(uv)-s;
    return max(l.x, l.y);
}

float _cube(vec3 p, vec3 s)
{
    vec3 l = abs(p)-s;
    return max(l.x, max(l.y, l.z));
}

float _cucube(vec3 p, vec3 s, vec3 th)
{
    float c = _cube(p, s);

    c = max(c, -_sqr(p.xy, s.xy-th.xy));
    c = max(c, -_sqr(p.yz, s.yz-th.yz));
    c = max(c, -_sqr(p.xz, s.xy-th.xz));
    return c;
}
#define PI acos(-1.)

float pattern(vec2 uv)
{
    uv = abs(uv);
    uv.y -= .1+0.05*sin(iTime*.1);
    uv *= rot(length(uv)+iTime*.1);
    uv = abs(uv);
    uv.y -= .1+0.05*sin(iTime*.3);
    uv.x -= .15+0.05*sin(iTime*.25);
    uv *= rot(length(uv)-iTime*.13);
    float c = abs(_sqr(uv*rot(PI*.25), vec2(.2)))-0.1;
    c = min(c, abs(_sqr(uv*rot(PI*.5), vec2(.1)))-0.1);
    c = abs(c)-0.05;
    c = min(c, abs(_sqr(uv*rot(PI*.5), vec2(.05)))-0.1);
    c = abs(c)-0.01;
    c = min(c, abs(_sqr(uv*rot(PI*.5), vec2(.18)))-0.01);

    return c;
}

float pattern2(vec2 uv)
{
    return min(min(pattern(uv), pattern(uv.yx*1.2)), pattern(uv.yx*.5));
}

vec3 position;

vec2 map(vec3 p)
{
    p.xy *= rot(PI*.25);
    p = abs(p);
    vec2 acc = vec2(1000.,-1.);

    vec3 pc = p;
    pc.xy *= rot(-iTime*.1);
    pc.yz *= rot(sin(iTime*.15)*.5);
    position = pc;
    float c = _cube(pc, vec3(1.));

       c -= pattern2(position.xy*.7)*2.; 
    acc = _min(acc, vec2(c, 1.));

    return acc;
}

vec3 getNorm(vec3 p)
{
    vec2 e = vec2(0.01,0.);
    float d = map(p+e.xxx).x;
    return normalize(vec3(d)-vec3(
        map(p-e.xyy).x,
        map(p-e.yxy).x,
        map(p-e.yyx).x));
}




vec3 rdr(vec2 uv)
{
    vec3 col = vec3(0.149,0.102,0.157)*(1.-sat(length(uv)*1.5));

    vec3 ro = vec3(0.,0.,-5.);
    vec3 rd = normalize(vec3(uv, 1.));
    vec3 p = ro;
    vec3 acc = vec3(0.);
    for (int i = 0; i < 200; ++i)
    {
        vec2 res = map(p);
        if (distance(p, ro) > 10.)
            break;
        if (res.x < 0.001)
        {
//            col = vec3(1.);
            vec3 n = getNorm(p);
            float pat = pattern2(position.xy*.7);
            float gloss = mix(5.,15.,sat(pat*500.))*2.;
            float glossrefl = mix(1.,0.5,sat(pat*500.))*1.;
            float glossreflopa = mix(0.4,.8,sat((pat-.02)*500.))*1.;
            vec3 ldir = -normalize(vec3(5.,5.,-5.));
            col =.5*mix(vec3(.025), vec3(0.01), 1.-sat((pat-.01)*500.))*sat(dot(ldir, n));
            vec3 refl = normalize(reflect(rd, n)
            +glossrefl*(vec3(rand(), rand(), rand())-.5));
            vec3 h = normalize(-rd+ldir);
            col += glossreflopa*texture(iChannel1, refl).xyz*vec3(0.310,0.267,0.267);
            col += .2*vec3(0.957,0.663,0.043)*pow(sat(dot(h, n)),gloss);
            break;
        }
//        acc += (sin(p)*.5+.5)*(1.-sat(res.x/.2))*.01;
        p+= rd * res.x;
    }
    col += acc;
    return col;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord-.5*iResolution.xy)/iResolution.xx;
    _seed = iTime + texture(iChannel0, uv.xyx).x;
    vec3 col = rdr(uv*1.5);
    col = pow(col, vec3(1.8));
    col *= 10.4;
    col = col.xxx;
    col = sat(col);
//    col = atan(col);
    float patt = pattern(uv);
//    col = vec3(1.)*(1.-sat(patt*500.));

    fragColor = vec4(col,1.0);
}
